<script>document.addEventListener('DOMContentLoaded',()=>{const m=document.querySelector('[data-ec97-menu]'),n=document.querySelector('[data-ec97-nav]');m?.addEventListener('click',()=>n?.classList.toggle('is-open'));const r=document.querySelector('[data-ec97-slider]');if(r){const s=[...r.querySelectorAll('[data-ec97-slide]')];let i=0;if(s.length>1)setInterval(()=>{s[i].classList.remove('is-active');i=(i+1)%s.length;s[i].classList.add('is-active')},Number(r.dataset.autoplay)||5200)}});</script>
